#include <stdio.h>
#include <stdlib.h>

static int cmp_ll(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    long long K;
    if (scanf("%d %lld", &N, &K) != 2) return 0;

    long long *a = (long long *)malloc(sizeof(long long) * N);
    for (int i = 0; i < N; i++) scanf("%lld", &a[i]);

    qsort(a, N, sizeof(long long), cmp_ll);

    /* 
       A card a[i] is necessary iff there exists a subset of other cards with sum s
       such that K - a[i] <= s < K.
       If no such s exists, then whenever a subset containing a[i] is good,
       removing a[i] still keeps sum >= K, so a[i] is unnecessary.

       This property is monotone after sorting:
       if a[i] is necessary, then any larger card is also necessary.
       So we binary search the first necessary card.

       To test whether a[mid] is necessary, do subset-sum DP up to K-1 excluding a[mid],
       and check if any reachable sum lies in [K-a[mid], K-1].
    */

    int ng = -1, ok = N; /* first necessary index */

    while (ok - ng > 1) {
        int mid = (ok + ng) / 2;

        char *dp = (char *)calloc((size_t)K, sizeof(char));
        dp[0] = 1;

        for (int i = 0; i < N; i++) {
            if (i == mid) continue;
            long long w = a[i];
            if (w >= K) continue; /* sums >= K are irrelevant */
            for (long long s = K - 1 - w; s >= 0; s--) {
                if (dp[s]) dp[s + w] = 1;
            }
        }

        long long L = K - a[mid];
        if (L < 0) L = 0;

        int necessary = 0;
        for (long long s = L; s < K; s++) {
            if (dp[s]) {
                necessary = 1;
                break;
            }
        }

        free(dp);

        if (necessary) ok = mid;
        else ng = mid;
    }

    /* cards before ok are unnecessary */
    printf("%d\n", ok);

    free(a);
    return 0;
}

