int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    cin >> N >> K;
    vector<int> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    sort(a.begin(), a.end());

    auto necessary = [&](int idx) -> bool {
        // Check whether card a[idx] is necessary.
        // It is necessary iff there exists a subset of other cards with sum in [K-a[idx], K-1].
        // Then adding a[idx] makes it good, but removing it makes it not good.
        int x = a[idx];
        if (x >= K) return true; // empty subset already gives witness

        vector<char> dp(K, 0);
        dp[0] = 1;

        for (int i = 0; i < N; ++i) {
            if (i == idx) continue;
            int v = a[i];
            for (int s = K - 1 - v; s >= 0; --s) {
                if (dp[s]) dp[s + v] = 1;
            }
        }

        for (int s = max(0, K - x); s <= K - 1; ++s) {
            if (dp[s]) return true;
        }
        return false;
    };

    int unnecessary = 0;
    for (int i = 0; i < N; ++i) {
        if (!necessary(i)) ++unnecessary;
    }

    cout << unnecessary << '\n';
    return 0;
}

