public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = sc.nextInt();

        int totalSum = 0;
        for (int x : a) totalSum += x;

        int unnecessary = 0;

        for (int i = 0; i < N; i++) {
            int v = a[i];
            // Check if subset sum of cards except i can hit [K-v, K-1]
            if (K - v > K - 1) { // K-v > K-1 means v < 1, impossible since positive
                unnecessary++;
                continue;
            }
            if (K - 1 < 0) { // K <= 0, every subset is good, card is unnecessary
                unnecessary++;
                continue;
            }

            boolean[] dp = new boolean[totalSum + 1];
            dp[0] = true;
            for (int j = 0; j < N; j++) {
                if (j == i) continue;
                for (int s = totalSum; s >= a[j]; s--) {
                    if (dp[s - a[j]]) dp[s] = true;
                }
            }

            boolean needed = false;
            int lo = Math.max(0, K - v);
            int hi = K - 1;
            for (int s = lo; s <= hi && s <= totalSum; s++) {
                if (dp[s]) { needed = true; break; }
            }
            if (!needed) unnecessary++;
        }

        System.out.println(unnecessary);
    }
}

