import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        int K = fs.nextInt();
        int[] a = new int[N];
        for (int i = 0; i < N; i++) a[i] = fs.nextInt();

        Arrays.sort(a);

        int low = 0, high = N; // [0, low) unnecessary, [high, N) necessary
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (isUnnecessary(a, N, K, mid)) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        System.out.println(low);
    }

    static boolean isUnnecessary(int[] a, int N, int K, int idx) {
        if (a[idx] >= K) return false; // {a[idx]} itself is good, removing it breaks goodness

        boolean[] dp = new boolean[K];
        dp[0] = true;

        for (int i = 0; i < N; i++) {
            if (i == idx) continue;
            int v = a[i];
            for (int s = K - 1; s >= 0; s--) {
                if (!dp[s]) continue;
                int ns = s + v;
                if (ns >= K) ns = K - 1; // sums >= K are not needed separately
                dp[ns] = true;
            }
        }

        // If there exists a subset sum s in [K-a[idx], K-1],
        // then adding a[idx] makes it good, and removing a[idx] makes it not good.
        int need = K - a[idx];
        if (need < 0) need = 0;
        for (int s = need; s < K; s++) {
            if (dp[s]) return false; // necessary
        }
        return true; // unnecessary
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

